#include <bits/stdc++.h>
using namespace std;

struct Edge {
  int from, to;
  double length;
  Edge(int f, int t, double l): from(f), to(t), length(l) {}
};

struct Node {
  vector<int> out;
};

struct Graph {
  vector<Node> nodes;
  vector<Edge> edges;

  Graph(int nr_nodes, int nr_edges) {
    nodes.resize(nr_nodes);
    edges.reserve(nr_edges);
  }

  void add_edge(int from, int to, double length) {
    edges.emplace_back(from, to, length);
    nodes[from].out.push_back(edges.size()-1);
  }

  vector<int> find_augmenting_path(int source, int sink,
      vector<double> flow, double *path_cap) {
    set<pair<double, int>, greater<pair<double,int>>> q;
    vector<double> capacity(nodes.size(), 0);
    vector<int> pred(nodes.size(), -1);

    capacity[source] = INFINITY;
    q.emplace(INFINITY, source);

    while (!q.empty() && capacity[sink] == 0) {
      double cap = q.begin()->first;
      int n = q.begin()->second;
      q.erase(q.begin());

      for (int idx : nodes[n].out) {
        Edge &e = edges[idx];
        double e_cap = e.length - flow[idx];
        if (e_cap > 0 && min(cap, e_cap) > capacity[e.to]) {
          q.erase({capacity[e.to], e.to});
          capacity[e.to] = min(cap, e_cap);
          q.emplace(capacity[e.to], e.to);
          pred[e.to] = idx;
        }
      }
    }

    *path_cap = capacity[sink];
    vector<int> path;
    for (int e_idx = pred[sink]; e_idx != -1; e_idx = pred[edges[e_idx].from])
      path.push_back(e_idx);
    return path;
  }

  double max_flow(int source, int sink) {
    Graph residual(nodes.size(), 2*edges.size());
    vector<double> flow(2*edges.size(), 0);

    for (size_t i = 0; i < edges.size(); i++) {
      residual.add_edge(edges[i].from, edges[i].to, edges[i].length);
      residual.add_edge(edges[i].to, edges[i].from, 0);
    }

    double max_flow = 0;
    double path_cap;
    vector<int> path;
    while ((path = residual.find_augmenting_path(source, sink, flow, &path_cap)).size() && path_cap > 0) {
      for (int e_idx : path) {
        int e_ridx = (e_idx % 2) ? e_idx - 1 : e_idx + 1;
        flow[e_idx] += path_cap;
        flow[e_ridx] -= path_cap;
      }
    }

    for (int idx : residual.nodes[source].out)
      max_flow += flow[idx];
    return max_flow;
  }
};

int n, t;
struct Room {
  int i, j;
  array<bool, 61> infected{}, accessible{};
  int scientists = 0, capsules = 0;

  Room() { fill(accessible.begin(), accessible.end(), true); }

  int get_node_id(int timestamp) const {
    return 2 + i + n*j + (n*n)*timestamp;
  }

  void set_reactor() { fill(accessible.begin(), accessible.end(), false); }

  void set_infected(int timestamp = 0) {
    if (accessible[timestamp]) {
      accessible[timestamp] = false;
      infected[timestamp] = true;
    }
  }

  void spread_infection(int timestamp);
};

array<array<Room, 10>, 10> floorplan;

void Room::spread_infection(int timestamp) {
  if (infected[timestamp]) {
    set_infected(timestamp + 1);
    if (i > 0) floorplan[i-1][j].set_infected(timestamp + 1);
    if (i < n-1) floorplan[i+1][j].set_infected(timestamp + 1);
    if (j > 0) floorplan[i][j-1].set_infected(timestamp + 1);
    if (j < n-1) floorplan[i][j+1].set_infected(timestamp + 1);
  }
}

string id_to_string(int id) {
  if (id == 0) return "source";
  if (id == 1) return "sink";
  ostringstream oss;
  int row = (id - 2) % n;
  int col = ((id - 2 - row) % (n*n)) / n;
  int timestamp = (id - 2 - row - col*n) / (n*n);
  oss << "(" << row << "," << col << "," << timestamp << ")";
  return oss.str(); 
}

int main() {
  ios::sync_with_stdio(false);
  cin >> n >> t;

  for (int i = 0; i < n; i++) {
    string line;
    cin >> line;
    for (int j = 0; j < n; j++) {
      floorplan[i][j].i = i;
      floorplan[i][j].j = j;
      if (line[j] == 'Y') floorplan[i][j].set_reactor();
      else if (line[j] == 'Z') floorplan[i][j].set_infected();
      else floorplan[i][j].scientists = line[j] - '0';
    }
  }

  for (int i = 0; i < n; i++) {
    string line;
    cin >> line;
    for (int j = 0; j < n; j++) {
      if (line[j] != 'Y' && line[j] != 'Z')
        floorplan[i][j].capsules = line[j] - '0';
    }
  }

  for (int c = 0; c <= t; c++) {
    for (int i = 0; i < n; i++) {
      for (int j = 0; j < n; j++) {
        if (c < t) floorplan[i][j].spread_infection(c);
      }
    }
  }

  Graph g(n*n*(t+1)+2, 100*4*60);
  for (int i = 0; i < n; i++) {
    for (int j = 0; j < n; j++) {
      const Room &room = floorplan[i][j];
      if (room.scientists > 0) g.add_edge(0, room.get_node_id(0), room.scientists);
      if (room.capsules > 0) g.add_edge(room.get_node_id(t), 1, room.capsules);
      for (int c = 0; c < t; c++) {
        if (room.capsules > 0) g.add_edge(room.get_node_id(c), room.get_node_id(t), 1000);
        if (room.accessible[c]) {
          if (i > 0 && floorplan[i-1][j].accessible[c])
            g.add_edge(room.get_node_id(c), floorplan[i-1][j].get_node_id(c+1), 1000);
          if (i < n-1 && floorplan[i+1][j].accessible[c])
            g.add_edge(room.get_node_id(c), floorplan[i+1][j].get_node_id(c+1), 1000);
          if (j > 0 && floorplan[i][j-1].accessible[c])
            g.add_edge(room.get_node_id(c), floorplan[i][j-1].get_node_id(c+1), 1000);
          if (j < n-1 && floorplan[i][j+1].accessible[c])
            g.add_edge(room.get_node_id(c), floorplan[i][j+1].get_node_id(c+1), 1000);
        }
      }
    }
  }

  cout << int(g.max_flow(0,1)) << "\n";
  return 0;
}
